[ExtensionOf(formStr(CustParameters))]
internal final class AVACustParametersFrm_Extension
{
    public SalesPurchSummarySumByCtrl sumByCtrl;
}

Method.Source:
/// <summary>
/// N.Freidenberger AVA 25.04.2024
/// </summary>
public void init()
{

    next init();
    FormComboBoxControl         sumUpdStandardPacking = this.design(0).controlName(formControlStr(CustParameters,'AVASumUpdateStandardPacking')) as FormComboBoxControl;
    sumByCtrl = SalesPurchSummarySumByCtrl::newSumByControl(sumUpdStandardPacking);
    sumByCtrl.setText(AccountOrder::Journal, '@SYS11549');
    sumByCtrl.build();

}

/// <summary>
/// N.Freidenberger    25.04.24
/// </summary>        
/// <param name = "_sumByCtrl">_sumByCtrl</param>
/// <returns>SalesPurchSummarySumByCtrl</returns>
SalesPurchSummarySumByCtrl parmsumByCtrl(SalesPurchSummarySumByCtrl _sumByCtrl = sumByCtrl)
{
    sumByCtrl = _sumByCtrl;
    return sumByCtrl;
}

/// <summary>
/// N.Freidenberger 26.04.2024
/// </summary>
public void run()
{
    next run();
    sumByCtrl.setSelection(salesParameters.AVASumByPacking);
    this.updateDesign();
}
